use std::io::{self, Read, Write};
use std::num::ParseIntError;

fn parse_one(tok: &str) -> Result<i64, ParseIntError> {
    tok.parse::<i64>()
}

fn parse_in_range(tok: &str, lo: i64, hi: i64) -> Result<i64, String> {
    let _ = (tok, lo, hi);
    Err(String::from("replace me"))
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let lo: i64 = match it.next() {
        Some(t) => t.parse().unwrap(),
        None => return,
    };
    let hi: i64 = it.next().unwrap().parse().unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    // one line per remaining token, then good / bad / total / fallback
    let _ = (&mut out, lo, hi, it);
}
